{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.PHILIPS_ZEPTO_FACT_ITEMS AS SELECT a.EAN, CONCAT(a.EAN, a.\"SKU Number\", a.CITY, a.DATE) AS ORDER_ITEM, REPLACE(c.MRP, \',\', \'\')::FLOAT AS MRP, a.CITY, CAST(a.DATE AS TIMESTAMP) AS ORDER_DATE, a.\"Brand Name\" AS BRAND, a.\"SKU Number\" AS SKU_NUMBER, b.PRIMARYKEY AS SKU, CAST(a.\"Sales (Qty) - Units\" AS INTEGER) AS QUANTITY, REPLACE(c.MRP, \',\', \'\')::FLOAT * CAST(a.\"Sales (Qty) - Units\" AS INTEGER) AS SELLING_PRICE, UPPER(b.PRODUCT_NAME) AS PRODUCT_NAME, UPPER(b.CATEGORY) AS PRODUCT_CATEGORY, UPPER(b.SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY FROM PHILIPS_DB.MAPLEMONK.ZEPTO_PHILIPS_SALES_SALES a LEFT JOIN ( SELECT DISTINCT \"ZEPTO ID\", PRIMARYKEY, CATEGORY, SUB_CATEGORY, \"PRODUCT TITLE\" AS PRODUCT_NAME FROM PHILIPS_DB.MAPLEMONK.PHILIPS_GS_SKU_MASTER ) b ON a.\"SKU Number\" = b.\"ZEPTO ID\" LEFT JOIN ( SELECT * FROM PHILIPS_DB.MAPLEMONK.PHILIPS_GS_SKU_MRP_COGS WHERE LOWER(MARKETPLACE) = \'zepto\' ) c ON UPPER(TRIM(b.PRIMARYKEY)) = UPPER(TRIM(c.SKU_CODE)) AND TO_DATE(a.DATE) BETWEEN c.START_DATE AND c.END_DATE WHERE TO_DATE(a.DATE) > ( SELECT MAX(DATE) FROM PHILIPS_DB.MAPLEMONK.QUICK_COMMERCE_HISTORICAL_SALES WHERE LOWER(PLATFORM) = \'zepto\' ) AND LOWER(COALESCE(b.PRODUCT_NAME, \'\')) NOT LIKE \'%mixer grinder%\' AND LOWER(COALESCE(b.PRODUCT_NAME, \'\')) NOT LIKE \'%blender%\' AND LOWER(COALESCE(b.PRODUCT_NAME, \'\')) NOT LIKE \'%speaker%\' AND LOWER(COALESCE(b.PRODUCT_NAME, \'\')) NOT LIKE \'%maaza%\' AND LOWER(COALESCE(b.PRODUCT_NAME, \'\')) NOT LIKE \'%lighting%\' UNION ALL SELECT NULL AS EAN, SKU_ITEM_ID AS ORDER_ITEM, MCSI AS MRP, UPPER(CITY) AS CITY, DATE AS ORDER_DATE, NULL AS BRAND, SKU_ITEM_ID AS SKU_NUMBER, CTN AS SKU, QTY::FLOAT AS QUANTITY, VALUE::FLOAT AS SELLING_PRICE, UPPER(ITEM_DESCRIPTION) AS PRODUCT_NAME, UPPER(BU) AS PRODUCT_CATEGORY, UPPER(SAG) AS PRODUCT_SUB_CATEGORY FROM PHILIPS_DB.MAPLEMONK.QUICK_COMMERCE_HISTORICAL_SALES a WHERE LOWER(PLATFORM) = \'zepto\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%mixer grinder%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%blender%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%speaker%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%maaza%\' AND LOWER(a.ITEM_DESCRIPTION) NOT LIKE \'%lighting%\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PHILIPS_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            